/** 
 * Releases all resources. <p>If the frame processor chain is released before it has  {@linkplain #isEnded() ended}, it will attempt to cancel processing any input frames that have already become available. Input frames that become available after release are ignored. <p>This method blocks until all OpenGL resources are released or releasing times out.
 */
public void release(){
  releaseRequested=true;
  while (!futures.isEmpty()) {
    checkNotNull(futures.poll()).cancel(true);
  }
  try {
    futures.add(singleThreadExecutorService.submit(() -> {
      for (int i=0; i < frameProcessors.size(); i++) {
        frameProcessors.get(i).release();
      }
      GlUtil.destroyEglContext(eglDisplay,eglContext);
    }));
  } catch (RejectedExecutionException e) {
    Log.e(TAG, "Failed to submit release task to executor", e);
  }
  if (inputSurfaceTexture != null) {
    inputSurfaceTexture.release();
  }
  if (inputSurface != null) {
    inputSurface.release();
  }
  singleThreadExecutorService.shutdown();
  try {
    if (!singleThreadExecutorService.awaitTermination(RELEASE_WAIT_TIME_MS,MILLISECONDS)) {
      Log.d(TAG,"Failed to release FrameProcessorChain");
    }
  } catch (InterruptedException e) {
    Log.d(TAG,"FrameProcessorChain release was interrupted",e);
  }
}
